#edf0e7;border-radius:15px;background:#fff;padding:9px 5px 7px;display:grid;justify-items:center;align-content:center;gap:3px;color:#667e81;cursor:pointer;transition:.15s}.item-card:hover{transform:translateY(-2px);border-color:#b4e5d4}.item-card.selected{border:2px solid #51c6a0;background:#effaf4;box-shadow:0 4px 12px #61bd9a23}.item-emoji{font-size:29px;line-height:32px;filter:saturate(.92)}.item-card b{font-size:10px;font-weight:700}.item-card small{font-size:8px;color:#b29c67}.panel-footer{min-height:49px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #edf0e7;color:#9aa8a3;font-size:9px}.panel-footer>span:first-child{color:#d3a548}.panel-footer button{border:0;border-radius:9px;background:#e8f6ef;color:#48a888;padding:7px 9px;font:700 10px 'DM Sans';cursor:pointer}.mobile-controls{position:absolute;z-index:4;bottom:103px;left:24px;right:24px;display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none}.dpad{pointer-events:auto;display:grid;gap:3px;justify-items:center}.dpad>button,.dpad div button{width:42px;height:39px;border:1px solid #ffffffd0;border-radius:13px;background:#ffffffd4;color:#547a85;font-size:21px;box-shadow:0 5px 14px #345e6c19;touch-action:none}.dpad div{display:flex;gap:3px}.action-button{pointer-events:auto;width:64px;height:64px;border:3px solid #fff;border-radius:50%;background:#ff8c77;color:white;box-shadow:0 7px 18px #d9776042;display:grid;place-content:center;gap:0;touch-action:none}.action-button span{font-size:21px}.action-button small{font-size:8px;font-weight:800}.desktop-help{position:absolute;bottom:28px;left:27px;color:#fff;text-shadow:0 1px 5px #387467;font-size:10px;font-weight:700}.desktop-help i{padding:0 5px;color:#f8e6a4}.toast{position:absolute;z-index:20;left:50%;bottom:108px;transform:translate(-50%,15px);padding:11px 17px;border-radius:14px;background:#355d61ed;color:white;box-shadow:var(--shadow);font-size:12px;font-weight:600;opacity:0;pointer-events:none;transition:.25s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:absolute;z-index:15;inset:0;background:#29495c55;display:grid;place-items:center;opacity:0;pointer-events:none;transition:.2s;backdrop-filter:blur(4px)}.modal-backdrop.open{opacity:1;pointer-events:auto}.modal{position:relative;width:min(410px,calc(100% - 34px));min-height:180px;padding:27px;border:1px solid #fff;border-radius:25px;background:#fffdf6;box-shadow:0 20px 70px #2648583b}.modal-close{position:absolute;right:16px;top:15px}.modal h2{font:600 25px Fredoka;margin:5px 0 8px}.modal p{font-size:13px;line-height:1.6;color:#788f93}.modal .big-emoji{font-size:46px}.modal-btn{border:0;border-radius:13px;padding:11px 17px;background:#51bd9a;color:white;font:700 12px 'DM Sans';cursor:pointer}.color-options{display:flex;gap:9px;margin:17px 0}.color-choice{width:34px;height:34px;border:3px solid white;outline:1px solid #dfe9df;border-radius:50%;cursor:pointer}.color-choice.selected{outline:2px solid #52bd9a}.hide{display:none!important}
