(()=>{
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const W=24,H=22,items=[
{id:'wall',name:'Parede pastel',emoji:'🧱',cat:'build',price:0,color:'#f7b99d',h:1},{id:'floor',name:'Piso de madeira',emoji:'🪵',cat:'build',price:0,color:'#dcae78',h:.22},{id:'road',name:'Caminho',emoji:'🟫',cat:'build',price:0,color:'#929da0',h:.14},{id:'window',name:'Janela',emoji:'🪟',cat:'build',price:25,color:'#78cfe2',h:.9},{id:'door',name:'Portinha',emoji:'🚪',cat:'build',price:30,color:'#ad7655',h:1},{id:'sofa',name:'Sofá coral',emoji:'🛋️',cat:'home',price:80,color:'#f18479',h:.65,interact:'sentar'},{id:'bed',name:'Cama fofinha',emoji:'🛏️',cat:'home',price:100,color:'#b7a0e8',h:.6,interact:'dormir'},{id:'table',name:'Mesa de chá',emoji:'🫖',cat:'home',price:55,color:'#d99a68',h:.7,interact:'tomar um chá'},{id:'tv',name:'TV colorida',emoji:'📺',cat:'home',price:120,color:'#4b6074',h:.8,interact:'assistir TV'},{id:'fridge',name:'Geladeira',emoji:'🧊',cat:'home',price:110,color:'#cce9e8',h:1.2,interact:'abrir a geladeira'},{id:'tree',name:'Árvore doce',emoji:'🌳',cat:'nature',price:45,color:'#65bd80',h:1.8},{id:'flower',name:'Flores',emoji:'🌷',cat:'nature',price:15,color:'#f38cb1',h:.55},{id:'pool',name:'Piscininha',emoji:'🏊',cat:'nature',price:180,color:'#58cce0',h:.2,interact:'dar um mergulho'},{id:'bench',name:'Banco do parque',emoji:'🪑',cat:'nature',price:60,color:'#cf9663',h:.55,interact:'sentar'},{id:'lamp',name:'Luminária',emoji:'💡',cat:'nature',price:40,color:'#ffe381',h:1.1},{id:'ball',name:'Bola de futebol',emoji:'⚽',cat:'fun',price:25,color:'#fff',h:.25,interact:'chutar'},{id:'hoop',name:'Cesta de basquete',emoji:'🏀',cat:'fun',price:95,color:'#ee9b56',h:1.5,interact:'arremessar'},{id:'car',name:'Carrinho fofo',emoji:'🚙',cat:'fun',price:300,color:'#ff796d',h:.58,interact:'dirigir'},{id:'swing',name:'Balanço',emoji:'🎠',cat:'fun',price:135,color:'#e6ab55',h:1.1,interact:'brincar'}
];
let userObjects=[],player={x:11.5,y:13.7},cam={x:0,y:0},mode='move',selected='wall',category='all',rotation=0,avatarColor='#f08d73',hair=0,driving=false,ballPos={x:15.4,y:10.1,vx:0,vy:0},toastTimer,walk=0,clockMin=41;
const data=localStorage.getItem('dream-island-save');if(data){try{let d=JSON.parse(data);userObjects=d.objects||[];player=d.player||player;avatarColor=d.avatar||avatarColor}catch{}}
const item=id=>items.find(o=>o.id===id);
function resize(){let d=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0)}window.addEventListener('resize',resize);resize();
function dimensions(){let r=canvas.getBoundingClientRect(),tile=Math.min(r.width/(W*1.25),r.height/(H*.78),42);tile=Math.max(22,tile);return {w:r.width,h:r.height,t:tile}}
function project(x,y,z=0){let {w,h,t}=dimensions();let cx=w/2+cam.x,cy=h*.54+cam.y;return {x:cx+(x-y)*t*.5,y:cy+(x+y)*t*.25-z*t*.48,t}}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function cube(x,y,z,color,depth=1){let p=project(x,y,z),t=p.t,hh=t*.48*depth,top=[{x:p.x,y:p.y-t*.25},{x:p.x+t*.5,y:p.y},{x:p.x,y:p.y+t*.25},{x:p.x-t*.5,y:p.y}];poly([{x:top[3].x,y:top[3].y},{x:top[2].x,y:top[2].y},{x:top[2].x,y:top[2].y+hh},{x:top[3].x,y:top[3].y+hh}],shade(color,-22));poly([{x:top[1].x,y:top[1].y},{x:top[2].x,y:top[2].y},{x:top[2].x,y:top[2].y+hh},{x:top[1].x,y:top[1].y+hh}],shade(color,-9));poly(top,color,'#6e967b26');return p}
function shade(hex,amt){let c=hex.replace('#','');if(c.length!==6)return hex;let n=parseInt(c,16),r=Math.max(0,Math.min(255,(n>>16)+amt)),g=Math.max(0,Math.min(255,((n>>8)&255)+amt)),b=Math.max(0,Math.min(255,(n&255)+amt));return `rgb(${r},${g},${b})`}
function tile(x,y,color){let p=project(x,y),t=p.t;poly([{x:p.x,y:p.y-t*.25},{x:p.x+t*.5,y:p.y},{x:p.x,y:p.y+t*.25},{x:p.x-t*.5,y:p.y}],color,'#ffffff14')}
const fixed=[];
function seed(){for(let y=0;y<H;y++)for(let x=0;x<W;x++){let edge=x<1||y<1||x>W-2||y>H-2;let park=x>2&&x<8&&y>3&&y<9;let road=(y===12||x===11||x===12);let plaza=x>8&&x<16&&y>8&&y<16;let col=edge?'#76c9d2':road?'#b9b8a7':plaza?'#ead9b8':park?'#8bd29a':((x+y)%2?'#86ce91':'#80c98b');fixed.push({x,y,color:col,kind:edge?'water':road?'road':plaza?'plaza':'grass'})}
const add=(id,x,y,extra={})=>fixed.push({id,x,y,...extra});
// Cozy village and public spaces
add('house',4,5,{color:'#ffd5a1'});add('house',7,15,{color:'#b8d9f3'});add('house',18,6,{color:'#f4b9bf'});
add('tree',3,4);add('tree',8,6);add('tree',5,9);add('tree',17,4);add('tree',20,8);add('tree',18,17);add('tree',4,17);add('tree',8,18);
add('flower',5,10);add('flower',6,10);add('flower',7,10);add('flower',3,11);add('flower',8,11);add('bench',9,10);add('bench',15,14);
add('car',13,12,{color:'#ff8270'});add('ball',15.3,9.3);add('house',19,15,{color:'#dac1f5'});add('lamp',9,13);add('lamp',16,11);add('pool',18,11);add('hoop',6,7);add('swing',3,7);
fixed.push({id:'cafe',x:10,y:5,color:'#ffcc8d'});fixed.push({id:'fountain',x:14,y:8});
}
seed();
function roundRect(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawHouse(o){let p=project(o.x,o.y),t=p.t,c=o.color||'#ffc98d';cube(o.x,o.y,0,c,1.8);let top=project(o.x,o.y,1.8);poly([{x:top.x-t*.5,y:top.y},{x:top.x,y:top.y-t*.33},{x:top.x+t*.5,y:top.y},{x:top.x,y:top.y+t*.33}],shade(c,-5));poly([{x:top.x-t*.57,y:top.y},{x:top.x,y:top.y-t*.46},{x:top.x+t*.57,y:top.y}],o.color?shade(o.color,-20):'#e88670');let front=project(o.x,o.y+.02,.65);roundRect(front.x-5,front.y-4,9,15,2,'#9b6655');let win=project(o.x-.45,o.y+.04,1.1);roundRect(win.x-5,win.y-3,9,8,2,'#90d4df');}
function drawTree(o){let p=project(o.x,o.y),t=p.t;cube(o.x,o.y,0,'#a8754d',.5);let q=project(o.x,o.y,.65);ctx.fillStyle='#56ae74';ctx.beginPath();ctx.arc(q.x,q.y-t*.29,t*.23,0,7);ctx.fill();ctx.fillStyle='#74c985';ctx.beginPath();ctx.arc(q.x-t*.11,q.y-t*.36,t*.16,0,7);ctx.fill();ctx.fillStyle='#97db91';ctx.beginPath();ctx.arc(q.x+t*.09,q.y-t*.23,t*.13,0,7);ctx.fill();}
function drawItem(o){let p=project(o.x,o.y),t=p.t;if(o.id==='house'){drawHouse(o);return}if(o.id==='tree'){drawTree(o);return}if(o.id==='ball'){let r=t*.12;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(p.x,p.y-t*.11,r,0,7);ctx.fill();ctx.strokeStyle='#596777';ctx.lineWidth=1;ctx.stroke();ctx.beginPath();ctx.moveTo(p.x-r*.6,p.y-t*.15);ctx.lineTo(p.x+r*.5,p.y-t*.07);ctx.stroke();return}if(o.id==='flower'){ctx.fillStyle='#5eab68';ctx.fillRect(p.x-1,p.y-t*.2,2,t*.22);ctx.fillStyle='#f58eb1';ctx.beginPath();ctx.arc(p.x,p.y-t*.25,t*.09,0,7);ctx.fill();ctx.fillStyle='#ffde78';ctx.beginPath();ctx.arc(p.x,p.y-t*.25,t*.035,0,7);ctx.fill();return}if(o.id==='pool'){let pts=[{x:p.x,y:p.y-t*.24},{x:p.x+t*.47,y:p.y},{x:p.x,y:p.y+t*.23},{x:p.x-t*.47,y:p.y}];poly(pts,'#56cbe1','#e9ffff');poly([{x:p.x,y:p.y-t*.13},{x:p.x+t*.29,y:p.y},{x:p.x,y:p.y+t*.14},{x:p.x-t*.29,y:p.y}], '#8ee5ee');return}if(o.id==='car'){cube(o.x,o.y,0,o.color||'#f87565',.38);let q=project(o.x,o.y,.4);roundRect(q.x-t*.22,q.y-t*.28,t*.44,t*.18,5,'#b9e8e9');for(let dx of [-.25,.25]){let w=project(o.x+dx,o.y+.12);ctx.fillStyle='#415967';ctx.beginPath();ctx.arc(w.x,w.y,t*.075,0,7);ctx.fill()}return}if(o.id==='bench'){cube(o.x,o.y,0,'#ba8359',.24);cube(o.x,o.y-.15,.25,'#d19a68',.18);return}if(o.id==='hoop'){cube(o.x,o.y,0,'#ddb37c',1);let q=project(o.x,o.y,1.05);ctx.strokeStyle='#e98757';ctx.lineWidth=3;ctx.beginPath();ctx.arc(q.x,q.y,t*.13,0,Math.PI);ctx.stroke();return}if(o.id==='swing'){cube(o.x,o.y,0,'#dba451',1.2);return}if(o.id==='cafe'||o.id==='fountain'){if(o.id==='cafe'){drawHouse({...o,id:'house'});return}cube(o.x,o.y,0,'#70cddb',.38);return}const it=item(o.id);if(!it)return;let color=o.color||it.color;if(o.id==='wall'){cube(o.x,o.y,0,color,1.35);return}cube(o.x,o.y,0,color,it.h||.5);if(o.id==='tv'){let q=project(o.x,o.y,.84);roundRect(q.x-t*.2,q.y-t*.34,t*.4,t*.23,3,'#526a82');roundRect(q.x-t*.16,q.y-t*.31,t*.32,t*.15,2,'#8bdde2')}if(o.id==='bed'){let q=project(o.x,o.y,.62);roundRect(q.x-t*.27,q.y-t*.48,t*.54,t*.25,4,'#fff0d6')}if(o.id==='fridge'){let q=project(o.x+.22,o.y,.55);ctx.fillStyle='#a5d5d9';ctx.fillRect(q.x,q.y-t*.12,2,t*.12)}}
function drawAvatar(){let p=project(player.x,player.y),t=p.t;let bob=Math.sin(walk)*t*.018;ctx.fillStyle='#46766335';ctx.beginPath();ctx.ellipse(p.x,p.y,t*.16,t*.08,0,0,7);ctx.fill();ctx.fillStyle='#47677a';roundRect(p.x-t*.10,p.y-t*.33+bob,t*.09,t*.23,4,'#597b92');roundRect(p.x+t*.01,p.y-t*.33-bob,t*.09,t*.23,4,'#597b92');let torso=p.y-t*.69+bob;roundRect(p.x-t*.16,torso,t*.32,t*.36,7,driving?'#f47766':avatarColor);ctx.fillStyle='#ffd2ae';ctx.beginPath();ctx.arc(p.x,torso-t*.12,t*.16,0,7);ctx.fill();ctx.fillStyle=hair===0?'#704934':hair===1?'#e7b052':'#554767';ctx.beginPath();ctx.arc(p.x,torso-t*.18,t*.16,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#52636a';ctx.beginPath();ctx.arc(p.x-t*.055,torso-t*.11,t*.018,0,7);ctx.arc(p.x+t*.055,torso-t*.11,t*.018,0,7);ctx.fill();ctx.strokeStyle='#d27e69';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(p.x,torso-t*.05,t*.045,.1,Math.PI-.1);ctx.stroke();}
function draw(){let {w,h,t}=dimensions();ctx.clearRect(0,0,w,h);let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#a8e7f2');sky.addColorStop(.55,'#c9efdf');sky.addColorStop(1,'#dbedc2');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);let sun=ctx.createRadialGradient(w*.78,h*.17,4,w*.78,h*.17,90);sun.addColorStop(0,'#fff7bd99');sun.addColorStop(1,'#fff7bd00');ctx.fillStyle=sun;ctx.fillRect(w*.62,h*.02,w*.32,h*.3);
// distant soft islands
ctx.fillStyle='#7dcba277';ctx.beginPath();ctx.ellipse(w*.14,h*.43,w*.24,40,-.12,0,7);ctx.ellipse(w*.84,h*.41,w*.3,50,.12,0,7);ctx.fill();
let ordered=[...fixed,...userObjects.map(o=>({...o,user:true}))].sort((a,b)=>(a.x+a.y)-(b.x+b.y));ordered.forEach(o=>{if(!o.id)tile(o.x,o.y,o.color);else drawItem(o)});
// ambient flowers and little path specks
for(let i=0;i<14;i++){let x=(i*7+3)%W,y=(i*11+5)%H;if((x+y)%4===0){let p=project(x+.5,y+.5);ctx.fillStyle='#fff6d2';ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(p.x,p.y,1.4,0,7);ctx.fill();ctx.globalAlpha=1}}
// placement ghost follows player for controller; mouse hover tracked separately
if(mode==='build'||mode==='decorate'){let p=project(hover.x,hover.y),t=p.t;ctx.globalAlpha=.35;drawItem({id:selected,x:hover.x,y:hover.y,color:'#67d9b2'});ctx.globalAlpha=1;}
drawAvatar();
if(ballPos.vx||ballPos.vy){ballPos.x+=ballPos.vx;ballPos.y+=ballPos.vy;ballPos.vx*=.96;ballPos.vy*=.96;if(Math.abs(ballPos.vx)+Math.abs(ballPos.vy)<.003)ballPos.vx=ballPos.vy=0;drawItem({id:'ball',...ballPos})}
requestAnimationFrame(draw)}
let hover={x:12,y:12};draw();
function screenToTile(sx,sy){let {w,h,t}=dimensions(),u=(sx-(w/2+cam.x))/(t*.5),v=(sy-(h*.54+cam.y))/(t*.25);return {x:Math.floor((u+v)/2),y:Math.floor((v-u)/2)}}
function showToast(text){let el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function save(){localStorage.setItem('dream-island-save',JSON.stringify({objects:userObjects,player,avatar:avatarColor}));showToast('✨ Seu mundinho foi salvo!')}
function place(x,y){x=Math.max(1,Math.min(W-2,x));y=Math.max(1,Math.min(H-2,y));if(selected==='erase'){userObjects=userObjects.filter(o=>Math.abs(o.x-x)+Math.abs(o.y-y)>0);showToast('🧹 Espaço limpinho!');return}const it=item(selected);if(!it)return;if(it.price>0){let coins=Number(localStorage.getItem('dream-coins')||2450);if(coins<it.price){showToast('🪙 Junte mais estrelinhas para comprar!');return}coins-=it.price;localStorage.setItem('dream-coins',coins);document.getElementById('coins').textContent=coins.toLocaleString('pt-BR')}
userObjects.push({id:selected,x,y,color:selected==='wall'?['#f5b69a','#b8d7f0','#c8e5a5','#f5d686'][rotation%4]:undefined,rotation});showToast(`${it.emoji} ${it.name} colocado!`);updateQuest();}
function setMode(m){mode=m;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));let panel=document.getElementById('buildPanel');panel.classList.toggle('open',m==='build'||m==='decorate'||m==='activities'||m==='avatar');if(m==='build'||m==='decorate'){category=m==='decorate'?'home':'all';renderCatalog();selected=m==='decorate'?'sofa':selected;renderCatalog()}if(m==='activities'){category='fun';renderCatalog();showToast('⚽ Escolha uma diversão e coloque no mundo!')}if(m==='avatar')openAvatar();document.getElementById('hintPill').textContent=m==='move'?'✨ Explore a ilha e encontre surpresas':m==='build'?'🧱 Toque no chão para construir':m==='decorate'?'🪴 Escolha algo bonito para decorar':'✨ Seu mundo, suas regras';}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));
function renderCatalog(){let root=document.getElementById('catalog');let list=items.filter(it=>category==='all'||it.cat===category);root.innerHTML=list.map(it=>`<button class="item-card ${selected===it.id?'selected':''}" data-id="${it.id}"><span class="item-emoji">${it.emoji}</span><b>${it.name}</b><small>${it.price?`✦ ${it.price}`:'Grátis'}</small></button>`).join('');root.querySelectorAll('.item-card').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.id;document.getElementById('selectedPrice').textContent=item(selected).price?`✦ ${item(selected).price}`:'Grátis';renderCatalog()}))}
document.querySelectorAll('.category').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;document.querySelectorAll('.category').forEach(c=>c.classList.toggle('active',c===b));renderCatalog()}));
renderCatalog();document.getElementById('rotateBtn').onclick=()=>{rotation=(rotation+1)%4;showToast('⟳ Peça girada!')};document.getElementById('closePanel').onclick=()=>setMode('move');document.getElementById('saveBtn').onclick=save;document.getElementById('questClose').onclick=()=>document.querySelector('.quest-card').classList.add('hide');document.getElementById('homeBtn').onclick=()=>{player={x:11.5,y:13.7};cam={x:0,y:0};showToast('🏝️ De volta à praça!')};
function nearest(){let list=[...fixed,...userObjects];return list.filter(o=>o.id&&Math.abs(o.x-player.x)+Math.abs(o.y-player.y)<2.1).sort((a,b)=>(Math.abs(a.x-player.x)+Math.abs(a.y-player.y))-(Math.abs(b.x-player.x)+Math.abs(b.y-player.y)))[0]}
function interact(){let o=nearest();if(driving){driving=false;showToast('🚙 Você saiu do carrinho!');return}if(!o){showToast('👀 Chegue mais perto de um objeto para interagir!');return}if(o.id==='car'){driving=true;showToast('🚙 Vrum! Use as setas para passear');return}if(o.id==='ball'){ballPos={x:o.x,y:o.y,vx:(player.x<o.x?.23:-.23),vy:-.12};showToast('⚽ Chutou para longe!');return}let it=item(o.id),act=it?.interact||({house:'entrar em casa',cafe:'pedir um lanchinho',fountain:'fazer um pedido'}[o.id]);if(act){showToast(({sentar:'🪑 Que bom descansar um pouquinho!',dormir:'😴 Bons sonhos!', 'assistir TV':'📺 Seu programa favorito começou!', 'abrir a geladeira':'🍓 Encontrou um lanchinho delicioso!', 'dar um mergulho':'💦 Splash! Água fresquinha!', 'tomar um chá':'🍵 Hora do chá!', 'brincar':'🎠 Uhuuul!', 'arremessar':'🏀 Cesta! Que talento!', 'entrar em casa':'🏠 Lar doce lar!', 'pedir um lanchinho':'🥐 Um lanchinho gostoso chegou!', 'fazer um pedido':'✨ Seu desejo está a caminho!'})[act]||`✨ Você foi ${act}!`)}else showToast('🌼 Que lugar bonito!')}
document.getElementById('actionBtn').onclick=interact;document.getElementById('interactBtn').onclick=interact;document.getElementById('vehicleBtn').onclick=()=>{let car=[...fixed,...userObjects].find(o=>o.id==='car');if(car){player.x=car.x-.4;player.y=car.y-.4;driving=true;showToast('🚙 Vrum! Passeie pela ilha com as setas')}else{selected='car';setMode('activities');showToast('🚙 Coloque um carrinho no seu mundo!')}};
document.getElementById('sportBtn').onclick=()=>{let ball=[...fixed,...userObjects].find(o=>o.id==='ball');if(ball){player.x=ball.x-.8;player.y=ball.y-.5;interact()}else{selected='ball';setMode('activities');showToast('⚽ Escolha uma bola no catálogo!')}};
function updateQuest(){let count=userObjects.length;document.getElementById('questText').textContent=count?`${count} itens criados • continue decorando!`:'Construa e decore sua ilha!';document.getElementById('questTitle').textContent=count>=5?'Você está arrasando!':'Um cantinho com a sua cara'}
let keys={};window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e'||k===' ')interact();if(k==='r'){rotation=(rotation+1)%4;showToast('⟳ Peça girada!')}if(k==='escape'){setMode('move');closeModal()}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function move(dx,dy){let speed=driving?.12:.07;player.x=Math.max(1,Math.min(W-2,player.x+dx*speed));player.y=Math.max(1,Math.min(H-2,player.y+dy*speed));walk+=.2;cam.x+=(dimensions().w/2-project(player.x,player.y).x)*.018;cam.y+=(dimensions().h*.54-project(player.x,player.y).y)*.018}
function frameMove(){let dx=0,dy=0;if(keys.w||keys.arrowup)dy-=1;if(keys.s||keys.arrowdown)dy+=1;if(keys.a||keys.arrowleft)dx-=1;if(keys.d||keys.arrowright)dx+=1;if(dx||dy)move(dx,dy);let clock=document.getElementById('clock');clockMin=(clockMin+.0007)%60;clock.textContent=`09:${String(Math.floor(clockMin)).padStart(2,'0')}`;requestAnimationFrame(frameMove)}frameMove();
document.querySelectorAll('.dpad button').forEach(b=>{let dir=b.dataset.dir,dx=dir==='left'?-1:dir==='right'?1:0,dy=dir==='up'?-1:dir==='down'?1:0;let interval;const start=e=>{e.preventDefault();move(dx,dy);interval=setInterval(()=>move(dx,dy),100)};const end=()=>clearInterval(interval);b.addEventListener('pointerdown',start);b.addEventListener('pointerup',end);b.addEventListener('pointerleave',end);b.addEventListener('pointercancel',end)});
let pointerDown=null;canvas.addEventListener('pointermove',e=>{let r=canvas.getBoundingClientRect();hover=screenToTile(e.clientX-r.left,e.clientY-r.top)});canvas.addEventListener('pointerdown',e=>{pointerDown={x:e.clientX,y:e.clientY,time:Date.now()}});canvas.addEventListener('pointerup',e=>{if(!pointerDown)return;let dist=Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y);if(dist>12){cam.x+=e.clientX-pointerDown.x;cam.y+=e.clientY-pointerDown.y;pointerDown=null;return}let r=canvas.getBoundingClientRect(),pos=screenToTile(e.clientX-r.left,e.clientY-r.top);if(mode==='build'||mode==='decorate'||mode==='activities'){place(pos.x,pos.y)}else{let dx=pos.x-player.x,dy=pos.y-player.y;if(Math.abs(dx)+Math.abs(dy)<2.3)interact();else{player.x=Math.max(1,Math.min(W-2,pos.x+.5));player.y=Math.max(1,Math.min(H-2,pos.y+.5));}}pointerDown=null});

