(()=>{
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');
const catalog=[['wall','Parede pastel','🧱','build',0,'#f3b99e',1],['floor','Piso de madeira','🪵','build',0,'#d7a977',.2],['road','Caminho','🟫','build',0,'#929da0',.2],['window','Janela','🪟','build',25,'#78cfe2',.8],['door','Portinha','🚪','build',30,'#ad7655',1],['sofa','Sofá coral','🛋️','home',80,'#f18479',.7,'sentar'],['bed','Cama fofinha','🛏️','home',100,'#b7a0e8',.6,'dormir'],['table','Mesa de chá','🫖','home',55,'#d99a68',.7,'tomar um chá'],['tv','TV colorida','📺','home',120,'#4b6074',.8,'assistir TV'],['fridge','Geladeira','🧊','home',110,'#cce9e8',1.2,'abrir a geladeira'],['tree','Árvore doce','🌳','nature',45,'#65bd80',1.8],['flower','Flores','🌷','nature',15,'#f38cb1',.5],['pool','Piscininha','🏊','nature',180,'#58cce0',.2,'dar um mergulho'],['bench','Banco do parque','🪑','nature',60,'#cf9663',.5,'sentar'],['lamp','Luminária','💡','nature',40,'#ffe381',1.1],['ball','Bola de futebol','⚽','fun',25,'#fff',.25,'chutar'],['hoop','Cesta de basquete','🏀','fun',95,'#ee9b56',1.5,'arremessar'],['car','Carrinho fofo','🚙','fun',300,'#ff796d',.5,'dirigir'],['swing','Balanço','🎠','fun',135,'#e6ab55',1.1,'brincar']].map(a=>({id:a[0],name:a[1],emoji:a[2],cat:a[3],price:a[4],color:a[5],h:a[6],act:a[7]}));
const get=id=>catalog.find(a=>a.id===id),W=24,H=22;let objects=[],player={x:11.5,y:13.7},cam={x:0,y:0},mode='move',chosen='wall',category='all',rotation=0,avatar='#f08d73',hair=0,driving=false,walk=0,hover={x:12,y:12},ball={x:15,y:9,vx:0,vy:0};
try{let s=JSON.parse(localStorage.getItem('dream-island-save')||'{}');objects=s.objects||[];player=s.player||player;avatar=s.avatar||avatar}catch{}
let fixed=[];for(let y=0;y<H;y++)for(let x=0;x<W;x++){let edge=x===0||y===0||x===W-1||y===H-1,road=x===11||x===12||y===12,park=x>2&&x<9&&y>3&&y<10,plaza=x>8&&x<16&&y>8&&y<16;fixed.push({x,y,tile:1,color:edge?'#79cbd2':road?'#b9b8a7':plaza?'#ead9b8':park?'#8bd29a':(x+y)%2?'#86ce91':'#80c98b'})}
const add=(id,x,y,color)=>fixed.push({id,x,y,color});[[4,5,'#ffd5a1'],[7,15,'#b8d9f3'],[18,6,'#f4b9bf'],[19,15,'#dac1f5']].forEach(a=>add('house',...a));[[3,4],[8,6],[5,9],[17,4],[20,8],[18,17],[4,17],[8,18]].forEach(a=>add('tree',...a));[[5,10],[6,10],[7,10],[3,11],[8,11]].forEach(a=>add('flower',...a));add('bench',9,10);add('bench',15,14);add('car',13,12,'#ff8270');add('ball',15,9);add('lamp',9,13);add('lamp',16,11);add('pool',18,11);add('hoop',6,7);add('swing',3,7);add('cafe',10,5);add('fountain',14,8);
function resize(){let d=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0)}window.addEventListener('resize',resize);resize();
function dim(){let r=canvas.getBoundingClientRect(),t=Math.max(22,Math.min(42,r.width/(W*1.25),r.height/(H*.78)));return {w:r.width,h:r.height,t}}
function project(x,y,z=0){let {w,h,t}=dim();return {x:w/2+cam.x+(x-y)*t*.5,y:h*.54+cam.y+(x+y)*t*.25-z*t*.48,t}}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function shade(c,n){let v=parseInt(c.slice(1),16);return `rgb(${Math.max(0,Math.min(255,(v>>16)+n))},${Math.max(0,Math.min(255,((v>>8)&255)+n))},${Math.max(0,Math.min(255,(v&255)+n))})`}
function cube(x,y,z,c,d=1){let p=project(x,y,z),t=p.t,h=t*.48*d,a=[{x:p.x,y:p.y-t*.25},{x:p.x+t*.5,y:p.y},{x:p.x,y:p.y+t*.25},{x:p.x-t*.5,y:p.y}];poly([a[3],a[2],{x:a[2].x,y:a[2].y+h},{x:a[3].x,y:a[3].y+h}],shade(c,-22));poly([a[1],a[2],{x:a[2].x,y:a[2].y+h},{x:a[1].x,y:a[1].y+h}],shade(c,-9));poly(a,c,'#6e967b26');return p}
function tile(x,y,c){let p=project(x,y),t=p.t;poly([{x:p.x,y:p.y-t*.25},{x:p.x+t*.5,y:p.y},{x:p.x,y:p.y+t*.25},{x:p.x-t*.5,y:p.y}],c,'#ffffff14')}
function rr(x,y,w,h,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawHouse(o){let p=project(o.x,o.y),t=p.t,c=o.color||'#ffc98d';cube(o.x,o.y,0,c,1.8);let q=project(o.x,o.y,1.8);poly([{x:q.x-t*.57,y:q.y},{x:q.x,y:q.y-t*.46},{x:q.x+t*.57,y:q.y}],shade(c,-17));let d=project(o.x,o.y+.02,.65);rr(d.x-5,d.y-4,9,15,2,'#9b6655');let w=project(o.x-.45,o.y+.04,1.1);rr(w.x-5,w.y-3,9,8,2,'#90d4df')}
function drawTree(o){let p=project(o.x,o.y),t=p.t;cube(o.x,o.y,0,'#a8754d',.5);let q=project(o.x,o.y,.65);for(let [dx,dy,r,c] of [[0,-.29,.23,'#56ae74'],[-.11,-.36,.16,'#74c985'],[.09,-.23,.13,'#97db91']]){ctx.fillStyle=c;ctx.beginPath();ctx.arc(q.x+dx*t,q.y+dy*t,r*t,0,7);ctx.fill()}}
function drawItem(o){let p=project(o.x,o.y),t=p.t;if(o.id==='house'){drawHouse(o);return}if(o.id==='tree'){drawTree(o);return}if(o.id==='ball'){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(p.x,p.y-t*.11,t*.12,0,7);ctx.fill();ctx.strokeStyle='#657681';ctx.stroke();return}if(o.id==='flower'){ctx.fillStyle='#5eab68';ctx.fillRect(p.x-1,p.y-t*.2,2,t*.22);ctx.fillStyle='#f58eb1';ctx.beginPath();ctx.arc(p.x,p.y-t*.25,t*.09,0,7);ctx.fill();ctx.fillStyle='#ffde78';ctx.beginPath();ctx.arc(p.x,p.y-t*.25,t*.035,0,7);ctx.fill();return}if(o.id==='pool'){poly([{x:p.x,y:p.y-t*.24},{x:p.x+t*.47,y:p.y},{x:p.x,y:p.y+t*.23},{x:p.x-t*.47,y:p.y}], '#56cbe1','#e9ffff');return}if(o.id==='car'){cube(o.x,o.y,0,o.color||'#f87565',.38);let q=project(o.x,o.y,.4);rr(q.x-t*.22,q.y-t*.28,t*.44,t*.18,5,'#b9e8e9');for(let dx of [-.25,.25]){let w=project(o.x+dx,o.y+.12);ctx.fillStyle='#415967';ctx.beginPath();ctx.arc(w.x,w.y,t*.075,0,7);ctx.fill()}return}if(o.id==='bench'){cube(o.x,o.y,0,'#ba8359',.24);cube(o.x,o.y-.15,.25,'#d19a68',.18);return}if(o.id==='hoop'){cube(o.x,o.y,0,'#ddb37c',1);let q=project(o.x,o.y,1.05);ctx.strokeStyle='#e98757';ctx.lineWidth=3;ctx.beginPath();ctx.arc(q.x,q.y,t*.13,0,Math.PI);ctx.stroke();return}if(o.id==='house')return;if(o.id==='cafe'){drawHouse({...o,id:'house'});return}if(o.id==='fountain'){cube(o.x,o.y,0,'#70cddb',.38);return}let it=get(o.id);if(!it)return;cube(o.x,o.y,0,o.color||it.color,it.h||.5);if(o.id==='tv'){let q=project(o.x,o.y,.84);rr(q.x-t*.2,q.y-t*.34,t*.4,t*.23,3,'#526a82');rr(q.x-t*.16,q.y-t*.31,t*.32,t*.15,2,'#8bdde2')}if(o.id==='bed'){let q=project(o.x,o.y,.62);rr(q.x-t*.27,q.y-t*.48,t*.54,t*.25,4,'#fff0d6')}}
function drawAvatar(){let p=project(player.x,player.y),t=p.t,b=Math.sin(walk)*t*.018;ctx.fillStyle='#46766335';ctx.beginPath();ctx.ellipse(p.x,p.y,t*.16,t*.08,0,0,7);ctx.fill();rr(p.x-t*.1,p.y-t*.33+b,t*.09,t*.23,4,'#597b92');rr(p.x+t*.01,p.y-t*.33-b,t*.09,t*.23,4,'#597b92');let top=p.y-t*.69+b;rr(p.x-t*.16,top,t*.32,t*.36,7,driving?'#f47766':avatar);ctx.fillStyle='#ffd2ae';ctx.beginPath();ctx.arc(p.x,top-t*.12,t*.16,0,7);ctx.fill();ctx.fillStyle=['#704934','#e7b052','#554767'][hair];ctx.beginPath();ctx.arc(p.x,top-t*.18,t*.16,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#52636a';ctx.beginPath();ctx.arc(p.x-t*.055,top-t*.11,t*.018,0,7);ctx.arc(p.x+t*.055,top-t*.11,t*.018,0,7);ctx.fill();ctx.strokeStyle='#d27e69';ctx.beginPath();ctx.arc(p.x,top-t*.05,t*.045,.1,Math.PI-.1);ctx.stroke()}

