function render(){let {w,h,t}=dim();ctx.clearRect(0,0,w,h);let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#a8e7f2');sky.addColorStop(.55,'#c9efdf');sky.addColorStop(1,'#dbedc2');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);let sun=ctx.createRadialGradient(w*.78,h*.17,4,w*.78,h*.17,90);sun.addColorStop(0,'#fff7bd99');sun.addColorStop(1,'#fff7bd00');ctx.fillStyle=sun;ctx.fillRect(w*.62,h*.02,w*.32,h*.3);ctx.fillStyle='#7dcba277';ctx.beginPath();ctx.ellipse(w*.14,h*.43,w*.24,40,-.12,0,7);ctx.ellipse(w*.84,h*.41,w*.3,50,.12,0,7);ctx.fill();[...fixed,...objects].sort((a,b)=>(a.x+a.y)-(b.x+b.y)).forEach(o=>o.tile?tile(o.x,o.y,o.color):drawItem(o));for(let i=0;i<14;i++){let x=(i*7+3)%W,y=(i*11+5)%H;if((x+y)%4===0){let p=project(x+.5,y+.5);ctx.fillStyle='#fff6d2';ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(p.x,p.y,1.4,0,7);ctx.fill();ctx.globalAlpha=1}}if(mode==='build'||mode==='decorate'||mode==='activities'){ctx.globalAlpha=.35;drawItem({id:chosen,x:hover.x,y:hover.y,color:'#67d9b2'});ctx.globalAlpha=1}drawAvatar();if(ball.vx||ball.vy){ball.x+=ball.vx;ball.y+=ball.vy;ball.vx*=.96;ball.vy*=.96;if(Math.abs(ball.vx)+Math.abs(ball.vy)<.003)ball.vx=ball.vy=0;drawItem({id:'ball',...ball})}requestAnimationFrame(render)}render();
function screenToTile(sx,sy){let {w,h,t}=dim(),u=(sx-(w/2+cam.x))/(t*.5),v=(sy-(h*.54+cam.y))/(t*.25);return {x:Math.floor((u+v)/2),y:Math.floor((v-u)/2)}}
let toastTimer;function toast(s){let e=document.querySelector('#toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2100)}
function save(){localStorage.setItem('dream-island-save',JSON.stringify({objects,player,avatar}));toast('✨ Seu mundinho foi salvo!')}
function updateQuest(){let n=objects.length;document.querySelector('#questText').textContent=n?`${n} itens criados • continue decorando!`:'Construa e decore sua ilha!';document.querySelector('#questTitle').textContent=n>=5?'Você está arrasando!':'Um cantinho com a sua cara'}
function place(x,y){x=Math.max(1,Math.min(W-2,x));y=Math.max(1,Math.min(H-2,y));let it=get(chosen);if(!it)return;let coins=Number(localStorage.getItem('dream-coins')||2450);if(it.price>coins){toast('🪙 Junte mais estrelinhas para comprar!');return}if(it.price){coins-=it.price;localStorage.setItem('dream-coins',coins);document.querySelector('#coins').textContent=coins.toLocaleString('pt-BR')}objects.push({id:chosen,x,y,color:chosen==='wall'?['#f5b69a','#b8d7f0','#c8e5a5','#f5d686'][rotation%4]:undefined,rotation});toast(`${it.emoji} ${it.name} colocado!`);updateQuest()}
function renderCatalog(){let root=document.querySelector('#catalog'),list=catalog.filter(i=>category==='all'||i.cat===category);root.innerHTML=list.map(i=>`<button class="item-card ${chosen===i.id?'selected':''}" data-id="${i.id}"><span class="item-emoji">${i.emoji}</span><b>${i.name}</b><small>${i.price?`✦ ${i.price}`:'Grátis'}</small></button>`).join('');root.querySelectorAll('.item-card').forEach(b=>b.onclick=()=>{chosen=b.dataset.id;document.querySelector('#selectedPrice').textContent=get(chosen).price?`✦ ${get(chosen).price}`:'Grátis';renderCatalog()})}
